    /// <summary>Vorrat des Studios: die Grundideen aus dem Profil plus weitere konkrete Ideen.</summary>
    public static IReadOnlyList<string> Pool(string? studio) =>
        [.. StudioProfiles.For(studio).Ideas, .. studio is not null && More.TryGetValue(studio, out var m) ? m : []];

    /// <summary>Gleicher Wert bei jedem Start (string.GetHashCode wechselt je Programmstart).</summary>
    static uint Stable(string s) { var h = 2166136261u; foreach (var c in s) { h ^= c; h *= 16777619u; } return h; }

    /// <summary>Vier Ideen für heute: täglich andere Auswahl (stabil über den Tag), schon genutzte kommen zuletzt; <paramref name="page"/> blättert weiter („Andere Ideen“).</summary>
    public static IReadOnlyList<string> Pick(IReadOnlyList<string> pool, DateOnly day, IReadOnlyCollection<string> used, int page = 0, int count = 4)
    {
        if (pool.Count == 0) return [];
        var seed = day.DayNumber * 7919 + pool.Count;
        var order = pool.Select(x => (x, k: (Stable(x) ^ (uint)seed) * 2654435761u % 100_000))
            .OrderBy(t => used.Contains(t.x) ? 1 : 0).ThenBy(t => t.k).Select(t => t.x).ToList();
        var start = page * count % Math.Max(1, order.Count);
        return Enumerable.Range(0, Math.Min(count, order.Count)).Select(i => order[(start + i) % order.Count]).ToList();
    }
